<?php

namespace App\Services\Transcription;

use App\Models\Recording;

/**
 * Deterministic, offline stand-in for a real speech-to-text provider.
 *
 * Bound whenever `recordings.transcriber` is "fake" (the default), so the
 * full upload -> transcribe -> summarize pipeline can run without an API
 * key -- for local development, demos, and the automated test suite.
 */
class FakeTranscriber implements TranscriberInterface
{
    public function transcribe(Recording $recording): TranscriptionResult
    {
        $text = sprintf(
            "[Demo transcript generated by FakeTranscriber for \"%s\"]\n\n".
            "Thanks everyone for joining. Today we walked through the Q3 roadmap, ".
            "reviewed the open items from last sprint, and agreed on next steps. ".
            "Sarah will follow up with the client about the revised timeline. ".
            "Priya is going to update the API documentation before Friday. ".
            "We also agreed to revisit the pricing page copy next week and ".
            "James will schedule a follow-up call with the design team.",
            $recording->original_filename,
        );

        return new TranscriptionResult(text: $text, language: 'en');
    }
}
